<?php $rows = $rows ?? []; ?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><strong>Surgery period: <?= esc($min_range ?? '') ?> to <?= esc($max_range ?? '') ?></strong><span class="text-muted small"><?= count($rows) ?> surgery record<?= count($rows) === 1 ? '' : 's' ?></span></div>
<?php if (empty($rows)) : ?><div class="alert alert-info mb-0">No surgery records were found for the selected criteria.</div><?php else : ?><table class="table table-sm table-bordered table-striped align-middle mb-0" style="font-size:.8rem"><thead class="table-light"><tr><th>Surgery Date</th><th>MR No.</th><th>Camp Code</th><th>Patient Name</th><th>Age</th><th>Sex</th><th>Address</th><th>Doctor Name</th><th>Systemic</th><th>Final Diagnosis</th><th>Eye</th><th>Surgery Code</th><th>Surgery Name</th><th>Specialty</th><th>Admission Date</th><th>Discharge Date</th><th>Scheduled Time</th><th>Remarks</th><th>Anaesthetist</th><th>Surgery Start</th><th>Surgery End</th><th>Actual Duration</th><th>Estimated Surgery Cost</th><th>Actual Surgery Cost</th></tr></thead><tbody><?php foreach ($rows as $row) : ?><tr><td><?= esc($row['surgery_date'] ?? '') ?></td><td><?= esc($row['mr_no'] ?? '') ?></td><td><?= esc($row['camp_code'] ?? '') ?></td><td><?= esc($row['patient_name'] ?? '') ?></td><td><?= esc($row['age'] ?? '') ?></td><td><?= esc($row['gender'] ?? '') ?></td><td><?= esc($row['address'] ?? '') ?></td><td><?= esc($row['doctor_name'] ?? '') ?></td><td><?= esc($row['systemic_history'] ?? '') ?></td><td><?= esc($row['final_diagnosis'] ?? '') ?></td><td><?= esc($row['procedure_side'] ?? '') ?></td><td><?= esc($row['surgery_code'] ?? '') ?></td><td><?= esc($row['surgery_name'] ?? '') ?></td><td><?= esc($row['specialty'] ?? '') ?></td><td><?= esc(substr((string) ($row['register_date'] ?? ''), 0, 10)) ?></td><td><?= esc(substr((string) ($row['discharge_date'] ?? ''), 0, 10)) ?></td><td><?= esc($row['scheduled_start_at'] ?? '') ?></td><td><?= esc($row['surgery_remark'] ?? '') ?></td><td><?= esc($row['anesthetist_name'] ?? '') ?></td><td><?= esc($row['actual_start_at'] ?? '') ?></td><td><?= esc($row['actual_end_at'] ?? '') ?></td><td><?= isset($row['actual_duration_minutes']) ? (int) $row['actual_duration_minutes'] . ' min' : '' ?></td><td class="text-end"><?= ($row['estimated_surgery_cost'] ?? null) !== null ? number_format((float) $row['estimated_surgery_cost'], 2) : '' ?></td><td class="text-end"><?= ($row['actual_surgery_cost'] ?? null) !== null ? number_format((float) $row['actual_surgery_cost'], 2) : '' ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>